(function() {
    'use strict';

    class SalesOptAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Sales Force Optimization';
            this.version = '1.1.0';
        }

        initialize(state) {
            var _fresh = !state.history || state.history.length === 0;
            if (_fresh || !state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    arr: 45000000,
                    quarterlyRevenue: 11250000,
                    quotaAttainment: 54,
                    attritionRate: 18,
                    pipelineCoverage: 7.2,
                    territoryVariance: 45,
                    teamMorale: 58,
                    forecastAccuracy: 62,
                    costOfSales: 15,
                    repCount: 32,
                    revenueHistory: [],
                    attainmentHistory: [],
                    healthHistory: [],
                    pipelineHistory: []
                };
            }
            if (_fresh || !state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    rebalanceEffort: 20,
                    variablePay: 35,
                    accelerator: 1.5,
                    hygieneThreshold: 90
                };
            }

            var ri = document.getElementById('rebalanceInput');
            if (ri) { ri.value = state.decisions.rebalanceEffort; }
            var rv = document.getElementById('rebalanceValue');
            if (rv) { rv.textContent = state.decisions.rebalanceEffort; }
            var vp = document.getElementById('variablePayInput');
            if (vp) { vp.value = state.decisions.variablePay; }
            var ai = document.getElementById('acceleratorInput');
            if (ai) { ai.value = state.decisions.accelerator; }
            var hi = document.getElementById('hygieneInput');
            if (hi) { hi.value = state.decisions.hygieneThreshold; }

            if (ri && rv) {
                ri.addEventListener('input', function() {
                    rv.textContent = ri.value;
                });
            }

            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var _submitBtn = document.getElementById('nextPeriodBtn');
            if (_submitBtn && _submitBtn.disabled) { return false; }

            var ri = document.getElementById('rebalanceInput');
            if (ri) decisions.rebalanceEffort = parseInt(ri.value);
            var vp = document.getElementById('variablePayInput');
            if (vp) decisions.variablePay = parseInt(vp.value);
            var ai = document.getElementById('acceleratorInput');
            if (ai) decisions.accelerator = parseFloat(ai.value);
            var hi = document.getElementById('hygieneInput');
            if (hi) decisions.hygieneThreshold = parseInt(hi.value);

            if (isNaN(decisions.rebalanceEffort) || decisions.rebalanceEffort < 0 || decisions.rebalanceEffort > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('rebalance_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.variablePay) || decisions.variablePay < 20 || decisions.variablePay > 70) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('variable_pay_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.accelerator) || decisions.accelerator < 1.0 || decisions.accelerator > 3.0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('accelerator_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.hygieneThreshold) || decisions.hygieneThreshold < 30 || decisions.hygieneThreshold > 180) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('hygiene_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;

            // --- Territory Model ---
            var oldVariance = ds.territoryVariance;
            var varianceReduction = d.rebalanceEffort * 0.35;
            ds.territoryVariance = Math.max(5, oldVariance - varianceReduction);
            var disruptionPenalty = d.rebalanceEffort > 30 ? (d.rebalanceEffort - 30) * 0.001 : 0;
            var territoryFactor = 1 - ds.territoryVariance / 100;

            // --- Compensation Model ---
            var payMixScore = 1 - Math.abs(d.variablePay - 30) / 50;
            payMixScore = Math.max(0, Math.min(1, payMixScore));

            var accelScore = 0;
            if (d.accelerator >= 1.3 && d.accelerator <= 2.2) {
                accelScore = 1 - Math.abs(d.accelerator - 1.7) / 0.9;
            } else if (d.accelerator > 2.2) {
                accelScore = 0.3;
            } else {
                accelScore = 0.2;
            }
            var compEffectiveness = payMixScore * 0.5 + accelScore * 0.5;

            // --- Pipeline Model ---
            var cleanupRate = (180 - d.hygieneThreshold) / 150;
            var coverageReduction = cleanupRate * 0.6;
            ds.pipelineCoverage = Math.max(2.5, ds.pipelineCoverage - coverageReduction);
            ds.pipelineCoverage += 0.15;
            ds.pipelineCoverage = Math.round(ds.pipelineCoverage * 10) / 10;

            var coverageQuality = 0;
            if (ds.pipelineCoverage >= 3.5 && ds.pipelineCoverage <= 4.5) {
                coverageQuality = 1;
            } else if (ds.pipelineCoverage < 3.5) {
                coverageQuality = ds.pipelineCoverage / 3.5;
            } else {
                coverageQuality = Math.max(0.3, 1 - (ds.pipelineCoverage - 4.5) / 5);
            }

            // Forecast accuracy
            var forecastDelta = (coverageQuality - 0.5) * 6 + (d.hygieneThreshold <= 90 ? 2 : -1);
            ds.forecastAccuracy = Math.min(95, Math.max(40, ds.forecastAccuracy + forecastDelta));
            ds.forecastAccuracy = Math.round(ds.forecastAccuracy);

            // Quota attainment
            var attainmentDelta = (compEffectiveness * 5 + territoryFactor * 3 + coverageQuality * 2 - 4) + (Math.random() * 3 - 1.5);
            ds.quotaAttainment = Math.min(82, Math.max(30, ds.quotaAttainment + attainmentDelta));
            ds.quotaAttainment = Math.round(ds.quotaAttainment * 10) / 10;

            // Team morale
            var moraleDelta = compEffectiveness * 2.5 - disruptionPenalty * 15 + (ds.quotaAttainment > 60 ? 1.5 : -2);
            ds.teamMorale = Math.min(95, Math.max(20, ds.teamMorale + moraleDelta));
            ds.teamMorale = Math.round(ds.teamMorale);

            // Attrition
            var attritionDelta = 0;
            if (d.variablePay > 45) attritionDelta += 1.5;
            if (ds.teamMorale > 70) attritionDelta -= 2;
            if (ds.quotaAttainment < 50) attritionDelta += 3;
            if (ds.quotaAttainment > 65) attritionDelta -= 1;
            attritionDelta += (Math.random() * 2 - 1);
            ds.attritionRate = Math.min(30, Math.max(5, ds.attritionRate + attritionDelta));
            ds.attritionRate = Math.round(ds.attritionRate);

            // Rep count
            var repsLost = Math.round(ds.repCount * (ds.attritionRate / 100) / 4);
            var repsHired = Math.round(repsLost * 0.7);
            ds.repCount = Math.max(24, ds.repCount - repsLost + repsHired);

            // Revenue
            var marketGrowth = 0.045;
            var effectiveGrowth = marketGrowth * (ds.quotaAttainment / 60) * (1 - disruptionPenalty) * (0.5 + territoryFactor * 0.5);
            ds.quarterlyRevenue = Math.round(ds.quarterlyRevenue * (1 + effectiveGrowth));
            ds.arr = ds.quarterlyRevenue * 4;

            // Cost of sales
            var variablePayout = ds.arr * (d.variablePay / 100) * (ds.quotaAttainment / 100) * (0.8 + d.accelerator * 0.15);
            ds.costOfSales = Math.round((variablePayout / ds.arr) * 1000) / 10;

            // Health score (0-100) weighted: territory 25%, comp 40%, pipeline 35%
            var tScore = Math.max(0, 100 - ds.territoryVariance * 2);
            var cScore = Math.round(compEffectiveness * 100);
            var pScore = Math.round(coverageQuality * 60 + (ds.forecastAccuracy / 95) * 40);
            var healthScore = Math.round(tScore * 0.25 + cScore * 0.40 + pScore * 0.35);

            // Push histories
            ds.revenueHistory.push(Math.round(ds.arr / 100000) / 10);
            ds.attainmentHistory.push(Math.round(ds.quotaAttainment));
            ds.healthHistory.push(healthScore);
            ds.pipelineHistory.push(ds.pipelineCoverage);

            var results = {
                period: state.currentPeriod,
                quarterlyRevenue: ds.quarterlyRevenue,
                arr: ds.arr,
                quotaAttainment: Math.round(ds.quotaAttainment),
                attritionRate: ds.attritionRate,
                pipelineCoverage: ds.pipelineCoverage,
                territoryVariance: Math.round(ds.territoryVariance),
                teamMorale: ds.teamMorale,
                forecastAccuracy: ds.forecastAccuracy,
                costOfSales: ds.costOfSales,
                healthScore: healthScore,
                territoryScore: Math.round(tScore),
                compScore: cScore,
                pipelineScore: pScore
            };

            // v1.1.0: prevent double-submit re-entrancy (double-applied quarter / duplicated
            // history rows). Re-enabled in _updateBriefing when the next quarter renders.
            var _submitBtn = document.getElementById('nextPeriodBtn');
            if (_submitBtn) { _submitBtn.disabled = true; }

            var self = this;
            var nextPeriod = state.currentPeriod + 1;
            if (nextPeriod <= (state.maxPeriods || 10)) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: nextPeriod });
                }, 500);
            }

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('arrDisplay', 'domainState.arr',
                (v) => '$' + (v / 1000000).toFixed(1) + 'M');
            uiManager.bind('attainmentDisplay', 'domainState.quotaAttainment',
                (v) => Math.round(v) + '%');
            uiManager.bind('attritionDisplay', 'domainState.attritionRate',
                (v) => v + '%');
            uiManager.bind('pipelineDisplay', 'domainState.pipelineCoverage',
                (v) => v + 'x');
            uiManager.bind('varianceDisplay', 'domainState.territoryVariance',
                (v) => Math.round(v) + '%');
            uiManager.bind('moraleDisplay', 'domainState.teamMorale');
            uiManager.bind('costDisplay', 'domainState.costOfSales', (v) => v + '%');
            uiManager.bind('forecastDisplay', 'domainState.forecastAccuracy', (v) => Math.round(v) + '%');
        }

        getChartConfig() {
            return {
                revenueChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'ARR ($M)',
                            data: [],
                            borderColor: '#2ecc71',
                            backgroundColor: 'rgba(46,204,113,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Annual Recurring Revenue ($M)', color: '#ccc' },
                            legend: { labels: { color: '#aaa' } }
                        },
                        scales: {
                            y: { beginAtZero: false, ticks: { color: '#999' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            x: { ticks: { color: '#999' }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                },
                healthChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Health Score',
                            data: [],
                            borderColor: '#3498db',
                            backgroundColor: 'rgba(52,152,219,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Sales System Health Score', color: '#ccc' },
                            legend: { labels: { color: '#aaa' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { color: '#999' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            x: { ticks: { color: '#999' }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.revenueHistory.map((_, i) => 'Q' + (i + 1));
            return {
                revenueChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.revenueHistory }]
                },
                healthChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.healthHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var healthScores = history.map(function(r) {
                return r.results && r.results.healthScore ? r.results.healthScore : 0;
            });
            var avgHealth = Math.round(healthScores.reduce(function(s, v) { return s + v; }, 0) / healthScores.length);
            var finalHealth = healthScores[healthScores.length - 1] || 0;
            var lastResult = history[history.length - 1].results || {};
            var finalArr = lastResult.arr || 0;
            var finalAttainment = lastResult.quotaAttainment || 0;

            var performance = 'Needs Improvement';
            if (finalHealth >= 75 && avgHealth >= 65) performance = 'Excellent';
            else if (finalHealth >= 60 && avgHealth >= 50) performance = 'Good';
            else if (finalHealth >= 45) performance = 'Developing';

            var insights = [];
            if (finalAttainment >= 65) {
                insights.push('Strong quota attainment achieved. Compensation design drove rep behavior effectively.');
            } else {
                insights.push('Quota attainment remained below target. Review the alignment between territory potential and quota expectations.');
            }
            if (lastResult.territoryVariance !== undefined && lastResult.territoryVariance <= 15) {
                insights.push('Territory balance is excellent. Workload is distributed equitably across the sales force.');
            } else if (lastResult.territoryVariance !== undefined && lastResult.territoryVariance > 25) {
                insights.push('Territory imbalance persists. Consider more aggressive rebalancing in future quarters.');
            }
            if (lastResult.pipelineCoverage !== undefined && lastResult.pipelineCoverage >= 3.5 && lastResult.pipelineCoverage <= 4.5) {
                insights.push('Pipeline coverage is in the optimal range. Forecast reliability should be strong.');
            } else if (lastResult.pipelineCoverage !== undefined && lastResult.pipelineCoverage > 5) {
                insights.push('Pipeline remains bloated. Tighten stage exit criteria and cleanup thresholds.');
            }
            if (lastResult.attritionRate !== undefined && lastResult.attritionRate <= 10) {
                insights.push('Attrition is well controlled. The compensation and culture strategy is retaining talent.');
            }

            return {
                finalHealthScore: finalHealth,
                averageHealthScore: avgHealth,
                finalARR: finalArr,
                finalQuotaAttainment: finalAttainment,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.domainState.territoryVariance > 30) return window.mySimulation.t('hint_high_variance');
            if (state.domainState.pipelineCoverage > 5.5) return window.mySimulation.t('hint_bloated_pipeline');
            if (state.domainState.teamMorale < 45) return window.mySimulation.t('hint_low_morale');
            if (state.domainState.attritionRate > 22) return window.mySimulation.t('hint_high_attrition');
            if (results && results.healthScore >= 70) return window.mySimulation.t('hint_good_progress');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'decisions.rebalanceEffort', label: 'Rebalance', i18nKey: 'col_rebalance' },
                { key: 'decisions.variablePay', label: 'Var Pay %', i18nKey: 'col_varpay', formatter: (v) => v + '%' },
                { key: 'decisions.accelerator', label: 'Accel.', i18nKey: 'col_accel', formatter: (v) => v + 'x' },
                { key: 'results.quotaAttainment', label: 'Attainment', i18nKey: 'col_attainment', formatter: (v) => v + '%' },
                { key: 'results.pipelineCoverage', label: 'Pipeline', i18nKey: 'col_pipeline', formatter: (v) => v + 'x' },
                { key: 'results.healthScore', label: 'Health', i18nKey: 'col_health' },
                { key: 'results.costOfSales', label: 'Cost %', i18nKey: 'col_cost', formatter: (v) => v + '%' },
                { key: 'results.forecastAccuracy', label: 'Forecast', i18nKey: 'col_forecast', formatter: (v) => v + '%' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:              `Sales Force Optimization`,
                    subtitle:           `NexaCore Solutions — VP of Sales Dashboard`,
                    period_label:       `Quarter`,
                    period_of:          `of`,
                    arr_label:          `Annual Recurring Revenue`,
                    attainment_label:   `Quota Attainment`,
                    attrition_label:    `Annual Attrition`,
                    pipeline_label:     `Pipeline Coverage`,
                    territory_label:    `Territory Variance`,
                    morale_label:       `Team Morale`,
                    cost_label:         `Cost of Sales`,
                    forecast_label:     `Forecast Accuracy`,
                    decisions_heading:  `Your Decisions`,
                    rebalance_label:    `Territory Rebalance Effort (0–100)`,
                    variable_pay_label: `Variable Pay % of OTE`,
                    accelerator_label:  `Above-Quota Accelerator (x)`,
                    hygiene_label:      `Pipeline Cleanup Threshold (days)`,
                    submit_btn:         `Submit Quarter`,
                    undo_btn:           `Undo Last Quarter`,
                    rebalance_warning:  `Rebalance effort must be between 0 and 100`,
                    variable_pay_warning: `Variable pay must be between 20% and 70%`,
                    accelerator_warning:  `Accelerator must be between 1.0x and 3.0x`,
                    hygiene_warning:    `Pipeline cleanup threshold must be between 30 and 180 days`,
                    hint_high_variance: `Territory workload variance is still high. Consider increasing rebalance effort to reduce the imbalance.`,
                    hint_bloated_pipeline: `The pipeline is still bloated. Lower the cleanup threshold to remove stalled deals and improve forecast accuracy.`,
                    hint_low_morale:    `Team morale is critically low. Review compensation fairness and reduce disruptive territory changes.`,
                    hint_high_attrition: `Attrition is dangerously high. Improve morale and ensure compensation is competitive for top performers.`,
                    hint_good_progress: `Strong progress! The sales system health is improving across all three dimensions.`,
                    col_rebalance:      `Rebalance`,
                    col_varpay:         `Var Pay %`,
                    col_accel:          `Accel.`,
                    col_attainment:     `Attainment`,
                    col_pipeline:       `Pipeline`,
                    col_health:         `Health`,
                    col_cost:           `Cost %`,
                    col_forecast:       `Forecast`,
